<script setup lang="ts">import {ref,onMounted} from 'vue';import {useRouter} from 'vue-router';import {studies} from '../stores/studies';import {datasets} from '../stores/datasets';import {groups} from '../stores/groups';import {runs} from '../stores/runs';import {canWrite} from '../stores/auth';import {useTask} from '../hooks/useTask';import PageHeading from '../components/common/PageHeading.vue';import Notice from '../components/common/Notice.vue';const name=ref(''),dataset=ref('demo-dataset'),group=ref('demo-group'),replicates=ref(200),seed=ref(42),q=ref(.95);const {error,busy,act}=useTask();const router=useRouter();onMounted(()=>Promise.all([studies.load(),datasets.load(),groups.load()]));function submit(){act(async()=>{await studies.create({name:name.value,dataset_id:dataset.value,group_id:group.value,replicates:replicates.value,seed:seed.value,tail_quantile:q.value});name.value=''})}function execute(id:string){act(async()=>{const r=await runs.create({study_id:id});await router.push('/results?run='+r.id)})}</script><template><PageHeading eyebrow="STUDY DESIGN / 03" title="在运行之前，锁定问题。" note="阶段时延按相邻里程碑配对。无完整里程碑、重复或负时延的票号隔离，保留原因。"/><div class="two-col"><section><article v-for="row in studies.items.value" :key="row.id" class="study-row"><p class="eyebrow">REPRODUCIBLE STUDY</p><h2>{{row.name}}</h2><dl><div><dt>尾部分位</dt><dd>P{{row.config.tail_quantile*100}}</dd></div><div><dt>重采样</dt><dd>{{row.config.replicates}}次</dd></div><div><dt>随机种子</dt><dd>{{row.config.seed}}</dd></div></dl><button v-if="canWrite()" @click="execute(row.id)" :disabled="busy">送入计算队列 →</button></article></section><form v-if="canWrite()" class="editor-panel" @submit.prevent="submit"><h2>新建研究</h2><label>研究名称<input v-model="name" required minlength="2"></label><label>观测批次<select v-model="dataset"><option v-for="d in datasets.items.value" :value="d.id" :key="d.id">{{d.name}}</option></select></label><label>线路范围<select v-model="group"><option v-for="g in groups.items.value" :value="g.id" :key="g.id">{{g.name}}</option></select></label><div class="form-pair"><label>尾部分位<select v-model.number="q"><option :value=".9">P90</option><option :value=".95">P95</option><option :value=".99">P99</option></select></label><label>重采样次数<input type="number" v-model.number="replicates" min="30" max="1000"></label></div><label>随机种子<input type="number" v-model.number="seed" min="0" max="2147483647"></label><Notice :message="error"/><button :disabled="busy">保存研究口径</button></form></div></template>
